#pragma once
#include <string>
#include <vector>

// The jukebox as the game has it (DT_AlbumData_NN / DT_TrackData_NN): its albums, in the jukebox's
// order, and its tracks with their album, name and artist. MusicCatalog.cpp is generated by
// Tools\ExtractGameImages.py --catalog; the lookups are in MusicCatalogLookup.cpp.
namespace SonicRacingSaveManager::Data::MusicCatalog {

struct Album {
    int id;
    int order;              // where the jukebox lists it
    bool dlc;               // a collab character's: it comes with its pack (Steam), like the character
    const wchar_t* name[4];   // en, es, fr, it (the game names none: its jacket shows it)
};
struct Track {
    int id;
    int album;
    const wchar_t* name[4];   // en, es, fr, it
    const wchar_t* artist;
};

const std::vector<Album>& Albums();
const std::vector<Track>& Tracks();

const Album* FindAlbum(int id);
const Track* FindTrack(int id);
// Its name in a language ("en", "es", "fr", "it"; English for any other)
const wchar_t* AlbumName(const Album& a, const std::wstring& lang);
const wchar_t* TrackName(const Track& t, const std::wstring& lang);
// An album's tracks, by id
std::vector<int> TracksOf(int album);

} // namespace SonicRacingSaveManager::Data::MusicCatalog
